   214	func readMCPMessage(reader *bufio.Reader) (mcpMessage, error) {
   215		length := -1
   216		for {
   217			line, err := reader.ReadString('\n')
   218			if err != nil {
   219				return mcpMessage{}, err
   220			}
   221			line = strings.TrimRight(line, "\r\n")
   222			if line == "" {
   223				break
   224			}
   225			name, value, ok := strings.Cut(line, ":")
   226			if ok && strings.EqualFold(strings.TrimSpace(name), "Content-Length") {
   227				parsed, err := strconv.Atoi(strings.TrimSpace(value))
   228				if err != nil {
   229					return mcpMessage{}, err
   230				}
   231				if parsed < 0 {
   232					return mcpMessage{}, errors.New("Content-Length must be non-negative")
   233				}
   234				length = parsed
   235			}
   236		}
   237		if length < 0 {
   238			return mcpMessage{}, errors.New("missing Content-Length")
   239		}
   240		if length > maxMCPFrameBytes {
   241			return mcpMessage{}, fmt.Errorf("Content-Length exceeds maximum frame size of %d bytes", maxMCPFrameBytes)
   242		}
   243		data := make([]byte, length)
   244		if _, err := io.ReadFull(reader, data); err != nil {
   245			return mcpMessage{}, err
   246		}
   247		var msg mcpMessage
   248		if err := json.Unmarshal(data, &msg); err != nil {
   249			return mcpMessage{}, err
   250		}
   251		return msg, nil
   252	}
